    ? parseFloat(((dif_2000 / elv_2000)*100).toFixed(2)) : "N/A"
  const dif_2000_color   = dif_2000 !== "N/A"
    ? (dif_2000 &gt;= 0 ? "#198754" : "#dc3545") : "#6c757d"
